#!/bin/bash
# S-Mamba on PEMS07: input 96, horizons 12 24 48 96; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/PEMS/S_Mamba_PEMS07.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/PEMS/S_Mamba_PEMS07.sh   one seed on the CPU
# Results: output/long_term_forecast/PEMS07.tsv (one row per run); checkpoints: temp/checkpoints/PEMS07/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root PEMS07.npz)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 12: scripts/benchmark/official/S_Mamba/PEMS/S_Mamba_07.sh
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model S_Mamba \
    --des PEMS07_12_S_Mamba \
    --seed "$seed" \
    --root_path "$root" \
    --data_path PEMS07.npz \
    --data PEMS \
    --model_id PEMS07_96_12 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 12 \
    --enc_in 883 \
    --dec_in 883 \
    --c_out 883 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --no_time_marks \
    --pems_split itransformer \
    --e_layers 2 \
    --d_model 512 \
    --d_ff 512 \
    --batch_size 16 \
    --learning_rate 0.0007 \
    --use_norm 0 \
    $EXTRA_ARGS
done

